import Box from '@mui/material/Box'

export default function Paragraph() {
    return (
        <Box component="section" sx={{p: 2, width: '250vw'}}>
            <p style={{color: 'white'}}>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Duis ac orci sed purus pellentesque cursus ut nec leo. Phasellus at risus quis ante auctor facilisis. Fusce iaculis leo eget dui finibus, volutpat tincidunt erat euismod. Donec accumsan eget ligula at interdum. Lorem ipsum dolor sit amet, consectetur adipiscing elit. </p>
        </Box>
    )
}
